-- BidArena veritabanı şeması (PostgreSQL)
-- dbdiagram.io çıktısından türetildi; kurallar (CHECK), varsayılan tarihler,
-- eksik foreign key ve sorgu indeksleri eklendi.

CREATE TABLE "users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL,
  "full_name" varchar NOT NULL,
  "phone" varchar,
  "role" varchar NOT NULL DEFAULT 'USER' CHECK ("role" IN ('USER', 'ADMIN')),
  "is_verified" bool NOT NULL DEFAULT false,
  "restricted_until" timestamptz,
  "restriction_reason" varchar,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "subscriptions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "plan" varchar NOT NULL CHECK ("plan" IN ('INDIVIDUAL', 'PROFESSIONAL')),
  "listing_quota" int NOT NULL CHECK ("listing_quota" >= 0),
  "price_tl" int NOT NULL CHECK ("price_tl" >= 0),
  "status" varchar NOT NULL CHECK ("status" IN ('ACTIVE', 'EXPIRED', 'CANCELLED')),
  "starts_at" timestamptz NOT NULL,
  "ends_at" timestamptz NOT NULL,
  "payment_ref" varchar,
  CHECK ("ends_at" > "starts_at")
);

CREATE TABLE "listings" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "seller_id" int NOT NULL,
  "subscription_id" int NOT NULL,
  "title" varchar NOT NULL,
  "description" text,
  "defects" text,
  "category" varchar,
  "city" varchar,
  "district" varchar,
  "photos" jsonb,
  "safe_meeting_prefs" jsonb,
  "status" varchar NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'ACTIVE', 'CLOSED', 'CANCELLED')),
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "watchlist" (
  "user_id" int,
  "listing_id" int,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("user_id", "listing_id")
);

CREATE TABLE "auctions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "listing_id" int NOT NULL,
  "start_price" int NOT NULL CHECK ("start_price" > 0),
  "min_increment" int NOT NULL CHECK ("min_increment" > 0),
  "current_price" int NOT NULL,
  "highest_bid_id" int,
  "start_time" timestamptz NOT NULL,
  "end_time" timestamptz NOT NULL,
  "extension_count" int NOT NULL DEFAULT 0 CHECK ("extension_count" >= 0),
  "extension_window_sec" int NOT NULL DEFAULT 120 CHECK ("extension_window_sec" > 0), -- anti-sniping: son kaç saniye
  "extension_sec" int NOT NULL DEFAULT 120 CHECK ("extension_sec" > 0),               -- anti-sniping: ne kadar uzar
  "status" varchar NOT NULL DEFAULT 'SCHEDULED' CHECK ("status" IN ('SCHEDULED', 'ACTIVE', 'CLOSED')),
  "winner_id" int,
  CHECK ("end_time" > "start_time"),
  CHECK ("current_price" >= "start_price")
);

CREATE TABLE "bids" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "auction_id" int NOT NULL,
  "bidder_id" int NOT NULL,
  "amount" int NOT NULL CHECK ("amount" > 0),
  "is_auto" bool NOT NULL DEFAULT false,
  "idempotency_key" varchar NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "auto_bid_limits" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "auction_id" int NOT NULL,
  "user_id" int NOT NULL,
  "max_amount" int NOT NULL CHECK ("max_amount" > 0),
  "is_active" bool NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "appointments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "auction_id" int NOT NULL,
  "buyer_id" int NOT NULL,
  "seller_id" int NOT NULL,
  "agreed_price" int NOT NULL CHECK ("agreed_price" > 0),
  "location" varchar,
  "meeting_time" timestamptz,
  "buyer_accepted" bool NOT NULL DEFAULT false,
  "seller_accepted" bool NOT NULL DEFAULT false,
  "otp_hash" varchar,
  "otp_expires_at" timestamptz,
  "otp_used_at" timestamptz,
  "otp_failed_attempts" int NOT NULL DEFAULT 0 CHECK ("otp_failed_attempts" >= 0),
  "status" varchar NOT NULL DEFAULT 'PROPOSED' CHECK ("status" IN ('PROPOSED', 'CONFIRMED', 'MATCHED', 'COMPLETED',
                                     'NO_SHOW_BUYER', 'NO_SHOW_SELLER', 'ITEM_MISMATCH',
                                     'CANCELLED', 'DISPUTED')),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CHECK ("buyer_id" <> "seller_id")            -- kişi kendi ürününü alamaz
);

CREATE TABLE "delivery_confirmations" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "appointment_id" int NOT NULL,
  "user_id" int NOT NULL,
  "party" varchar NOT NULL CHECK ("party" IN ('BUYER', 'SELLER')),
  "confirmed_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "disputes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "appointment_id" int NOT NULL,
  "opened_by" int NOT NULL,
  "against_user_id" int NOT NULL,
  "type" varchar NOT NULL CHECK ("type" IN ('NO_SHOW', 'ITEM_MISMATCH', 'OTHER')),
  "description" text,
  "status" varchar NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'UNDER_REVIEW', 'UPHELD', 'REJECTED', 'APPEALED', 'CLOSED')),
  "resolution_note" text,
  "resolved_by" int,
  "appeal_note" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "resolved_at" timestamptz,
  CHECK ("opened_by" <> "against_user_id")
);

CREATE TABLE "evidence" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dispute_id" int NOT NULL,
  "uploaded_by" int NOT NULL,
  "file_url" varchar NOT NULL,
  "note" text,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "trust_events" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "party" varchar NOT NULL CHECK ("party" IN ('BUYER', 'SELLER')),
  "type" varchar NOT NULL CHECK ("type" IN ('SALE_COMPLETED', 'NO_SHOW', 'ITEM_MISMATCH')),
  "points" int NOT NULL,
  "verified" bool NOT NULL DEFAULT false,
  "appointment_id" int,
  "dispute_id" int,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "backup_offers" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "auction_id" int NOT NULL,
  "user_id" int NOT NULL,
  "bid_id" int NOT NULL,
  "price" int NOT NULL CHECK ("price" > 0),
  "rank" int NOT NULL CHECK ("rank" >= 1),
  "status" varchar NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING', 'ACCEPTED', 'REJECTED', 'EXPIRED')),
  "expires_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "responded_at" timestamptz
);

CREATE TABLE "notifications" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "type" varchar NOT NULL,
  "payload" jsonb,
  "is_read" bool NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "audit_logs" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" int,
  "action" varchar NOT NULL,
  "entity" varchar NOT NULL,
  "entity_id" int,
  "data" jsonb,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

-- Tekillik kuralları
CREATE UNIQUE INDEX ON "bids" ("bidder_id", "idempotency_key");          -- aynı teklif iki kez kaydedilmez
CREATE UNIQUE INDEX ON "auto_bid_limits" ("auction_id", "user_id");
CREATE UNIQUE INDEX ON "delivery_confirmations" ("appointment_id", "user_id");
CREATE UNIQUE INDEX ON "delivery_confirmations" ("appointment_id", "party");     -- her taraf bir kez onaylar
CREATE UNIQUE INDEX ON "auctions" ("listing_id")
  WHERE "status" IN ('SCHEDULED', 'ACTIVE');                            -- ilanın aynı anda tek canlı açık artırması; yeniden ilana çıkabilir
CREATE UNIQUE INDEX ON "backup_offers" ("auction_id", "user_id");
CREATE UNIQUE INDEX ON "backup_offers" ("auction_id", "rank");           -- her sırada tek yedek teklif
CREATE UNIQUE INDEX ON "backup_offers" ("auction_id")
  WHERE "status" = 'PENDING';                                           -- tek seferde yalnızca bir aktif yedek daveti (doküman F)

-- Sık yapılacak sorgular için indeksler
CREATE INDEX ON "bids" ("auction_id", "amount" DESC);                   -- en yüksek teklif
CREATE INDEX ON "auctions" ("status", "end_time");                      -- süresi biten açık artırmalar
CREATE INDEX ON "listings" ("status", "category", "city");              -- ilan arama
CREATE INDEX ON "notifications" ("user_id", "is_read");                 -- okunmamış bildirimler
CREATE INDEX ON "trust_events" ("user_id");                             -- güven puanı

COMMENT ON COLUMN "users"."restricted_until" IS 'gerekceli gecici kisit';
COMMENT ON COLUMN "subscriptions"."payment_ref" IS 'simule odeme kodu';
COMMENT ON COLUMN "listings"."defects" IS 'urun kusurlari';
COMMENT ON COLUMN "trust_events"."points" IS 'arti veya eksi puan';

-- Foreign key'ler
ALTER TABLE "subscriptions" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "listings" ADD FOREIGN KEY ("seller_id") REFERENCES "users" ("id");
ALTER TABLE "listings" ADD FOREIGN KEY ("subscription_id") REFERENCES "subscriptions" ("id");
ALTER TABLE "watchlist" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE;
ALTER TABLE "watchlist" ADD FOREIGN KEY ("listing_id") REFERENCES "listings" ("id") ON DELETE CASCADE;
ALTER TABLE "auctions" ADD FOREIGN KEY ("listing_id") REFERENCES "listings" ("id");
ALTER TABLE "auctions" ADD FOREIGN KEY ("winner_id") REFERENCES "users" ("id");
ALTER TABLE "auctions" ADD FOREIGN KEY ("highest_bid_id") REFERENCES "bids" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "bids" ADD FOREIGN KEY ("auction_id") REFERENCES "auctions" ("id");
ALTER TABLE "bids" ADD FOREIGN KEY ("bidder_id") REFERENCES "users" ("id");
ALTER TABLE "auto_bid_limits" ADD FOREIGN KEY ("auction_id") REFERENCES "auctions" ("id");
ALTER TABLE "auto_bid_limits" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "appointments" ADD FOREIGN KEY ("auction_id") REFERENCES "auctions" ("id");
ALTER TABLE "appointments" ADD FOREIGN KEY ("buyer_id") REFERENCES "users" ("id");
ALTER TABLE "appointments" ADD FOREIGN KEY ("seller_id") REFERENCES "users" ("id");
ALTER TABLE "delivery_confirmations" ADD FOREIGN KEY ("appointment_id") REFERENCES "appointments" ("id");
ALTER TABLE "delivery_confirmations" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "disputes" ADD FOREIGN KEY ("appointment_id") REFERENCES "appointments" ("id");
ALTER TABLE "disputes" ADD FOREIGN KEY ("opened_by") REFERENCES "users" ("id");
ALTER TABLE "disputes" ADD FOREIGN KEY ("against_user_id") REFERENCES "users" ("id");
ALTER TABLE "disputes" ADD FOREIGN KEY ("resolved_by") REFERENCES "users" ("id");
ALTER TABLE "evidence" ADD FOREIGN KEY ("dispute_id") REFERENCES "disputes" ("id") ON DELETE CASCADE;
ALTER TABLE "evidence" ADD FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id");
ALTER TABLE "trust_events" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "trust_events" ADD FOREIGN KEY ("appointment_id") REFERENCES "appointments" ("id");
ALTER TABLE "trust_events" ADD FOREIGN KEY ("dispute_id") REFERENCES "disputes" ("id");
ALTER TABLE "backup_offers" ADD FOREIGN KEY ("auction_id") REFERENCES "auctions" ("id");
ALTER TABLE "backup_offers" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "backup_offers" ADD FOREIGN KEY ("bid_id") REFERENCES "bids" ("id");
ALTER TABLE "notifications" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE;
ALTER TABLE "audit_logs" ADD FOREIGN KEY ("actor_id") REFERENCES "users" ("id");

-- Teslimat çift onay olmadan COMPLETED olamaz (doküman E ve 8)
CREATE FUNCTION check_double_confirmation() RETURNS trigger AS $$
BEGIN
  IF NEW."status" = 'COMPLETED' AND
     (SELECT count(DISTINCT "party") FROM "delivery_confirmations"
       WHERE "appointment_id" = NEW."id") < 2 THEN
    RAISE EXCEPTION 'Randevu % tamamlanamaz: alici ve satici onayi gerekli', NEW."id";
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER appointments_double_confirmation
  BEFORE INSERT OR UPDATE OF "status" ON "appointments"
  FOR EACH ROW EXECUTE FUNCTION check_double_confirmation();
